def state(profile):
    saved=profile.get('preferences',{}).get('automatic_features',{})
    overrides=saved.get('features',{})
    features={row['id']: overrides.get(row['id'], row['kind']!='write') for row in CATALOG}
    if 'demo_prep_booking' not in overrides:
        features['demo_prep_booking']=profile.get('preferences',{}).get('demo_prep_booking',{}).get('enabled') is True
    return {'schema_version':1,'revision':saved.get('revision',0),'features':features,
            'catalog':[{**row,'enabled':features[row['id']]} for row in CATALOG],
            'load_error':None,'authority':'Preferences only. Source access and every outside-world action still require your own approval.'}

def update(profile,body):
    current=state(profile)
    if body.get('revision')!=current['revision']:raise ValueError('Settings changed. Refresh before saving.')
    if body.get('action')!='set' or not isinstance(body.get('changes'),dict) or not body['changes']:raise ValueError('Choose feature changes')
    if any(k not in current['features'] or type(v) is not bool for k,v in body['changes'].items()):raise ValueError('Unknown feature or invalid choice')
    result=deepcopy(profile);features={**current['features'],**body['changes']}
    result.setdefault('preferences',{})['automatic_features']={'revision':current['revision']+1,'features':features}
    if 'demo_prep_booking' in body['changes']:
        result['preferences'].setdefault('demo_prep_booking',{})['enabled']=features['demo_prep_booking']
    return result
